                                'def test_agrega_acumula_duplicatas():\n'
                                '    regs = _ate("agrega")\n'
                                '    obtido = agrega(regs)\n'
                                '    assert obtido == TOT_ESP, _falha("agrega.py", "agrega", '
                                'TOT_ESP, obtido)\n'
                                '\n'
                                '\n'
                                'def test_valida_status_no_limite():\n'
                                '    tot = _ate("valida")\n'
