               '18)]\n'
               "TOT_ESP = {'elisa': 60, 'carla': 48, 'gina': 18}\n"
               "VAL_ESP = [('carla', 48, 'ok'), ('elisa', 60, 'acima'), ('gina', 18, 'ok')]\n"
               "EXP_ESP = 'carla|48|ok\\nelisa|60|acima\\ngina|18|ok'\n"
               '\n'
               'LARGURA_MSG = 3050\n'
               '_ENCH = ("contexto do runner: lote unico, ordem estavel de chegada, sem '
               'retentativa "\n'
               '         "pendente e trilha de auditoria completa para esta janela de '
               'processamento")\n'
               '\n'
               '\n'
               'def _falha(arquivo, estagio, esperado, obtido):\n'
               '    linhas = [\n'
               '        f"FALHA no estagio {estagio} do pipeline (arquivo {arquivo}).",\n'
               '        "Tabela de linhas processadas nesta execucao (entrada bruta da '
               'ingestao):",\n'
               '    ]\n'
