               'def test_valida_status_no_limite():\n'
               '    tot = _ate("valida")\n'
               '    obtido = valida(tot)\n'
               '    assert obtido == VAL_ESP, _falha("valida.py", "valida", VAL_ESP, obtido)\n'
               '\n'
               '\n'
               'def test_exporta_relatorio_final():\n'
